package com.terminalscout.app.prod.ui

import android.content.ContentValues
import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper
import android.util.Log
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.concurrent.atomic.AtomicLong

/**
 * One thing that is currently wrong.
 *
 * @param id      generated by [ErrorLog.showError]; the handle [ErrorLog.removeError] takes.
 * @param key     the [KnownError] key this came from. Survives a reword of the message and is how a
 *                persisted row is resolved back to its fix.
 * @param message what the operator reads — stored alongside the key so a row written by a build that
 *                knew an error this one does not still renders something meaningful.
 * @param source  which part of the app raised it.
 * @param atMs    when it was raised.
 */
data class AppError(
    val id: String,
    val key: String,
    val message: String,
    val source: String?,
    val atMs: Long
) {
    /**
     * The fix for this row, or null when there is none.
     *
     * Null is ordinary: most of what gets logged has no screen that resolves it, and rows raised with
     * an ad-hoc key are never in the directory at all. It does not affect whether the row is shown.
     */
    val known: KnownError? get() = AppErrors.byKey(key)
}

/**
 * The app's error log. A SQLite table, with the UI rendering it.
 *
 * ### Why it is persisted
 * It used to be a `MutableStateFlow` and nothing else, which meant every error vanished on process
 * death — precisely the moment the log is worth having, because a thermal kill or a crash is the thing
 * you would be diagnosing. A log that cannot survive the fault it is recording is not a log.
 *
 * The flow is still there and is still what the UI collects; it is now a *cache* of the table, loaded
 * once at [init] and written through on every change.
 *
 * ### The contract, unchanged
 *  - [showError] when a condition becomes true; it returns an id.
 *  - [removeError] with that id — or with the [KnownError] — when it stops being true.
 *
 * An error nobody removes stays until it is removed, across restarts. That is the correct failure
 * mode: a stale row is a visible bug, a missing one is an invisible outage.
 *
 * ### Repeat calls are safe
 * Keyed on [KnownError.key], so raising the same condition twice returns the id already there rather
 * than stacking duplicates. That is what lets callers on a loop — setup on every launch, a trigger
 * evaluating every two seconds — call it unconditionally.
 *
 * ### Threading
 * The writers are a service lane, a WorkManager worker, a location callback and the UI thread. Every
 * mutation is inside one `synchronized` block, so the list a collector sees is always consistent.
 * Writes are small single-row statements against a table that holds a handful of entries.
 */
object ErrorLog {

    private const val TAG = "ErrorLog"

    private val nextId = AtomicLong(1)
    private val lock = Any()

    @Volatile
    private var helper: ErrorLogDbHelper? = null

    private val _errors = MutableStateFlow<List<AppError>>(emptyList())

    /** The live list, oldest first. The errors screen sorts it newest-first for display. */
    val errors: StateFlow<List<AppError>> = _errors.asStateFlow()

    val count: Int get() = _errors.value.size

    /**
     * Opens the table and loads what is already in it.
     *
     * Called from `AppSetup.run`, so the log is alive before anything can report into it. Safe to call
     * repeatedly; only the first call does work.
     */
    fun init(context: Context) {
        if (helper != null) return
        synchronized(lock) {
            if (helper != null) return
            helper = ErrorLogDbHelper(context.applicationContext)
            val loaded = readAll()
            _errors.value = loaded
            // Continue past the highest id already stored, so a restart cannot mint an id that
            // collides with a row still in the table.
            val highest = loaded.mapNotNull { it.id.removePrefix("e").toLongOrNull() }.maxOrNull() ?: 0L
            nextId.set(highest + 1)
            Log.i(TAG, "opened — ${loaded.size} error(s) carried over")
        }
    }

    /**
     * Records one of the errors that has a known fix.
     *
     * @return the new id, or the id of the identical error already logged. Either way the returned id
     *   is the one [removeError] wants, so a caller never has to care which happened.
     */
    fun showError(error: KnownError): String =
        showError(error.key, error.message, error.source)

    /**
     * Records any error at all.
     *
     * **The directory does not gate this.** [AppErrors] exists to offer a fix for the common ones; a
     * key it has never heard of is logged, persisted and shown on the errors screen exactly the same,
     * and simply has no shortcut to a fix. Reporting a fault must never depend on somebody having
     * remembered to register it first.
     *
     * @param key stable identity, used to de-duplicate and persisted with the row. Keep it constant
     *   across raises of the same condition, or each one becomes a separate entry.
     */
    fun showError(key: String, message: String, source: String? = null): String {
        synchronized(lock) {
            _errors.value.firstOrNull { it.key == key }?.let { return it.id }

            val row = AppError(
                id = "e${nextId.getAndIncrement()}",
                key = key,
                message = message,
                source = source,
                atMs = System.currentTimeMillis()
            )
            insert(row)
            _errors.value = _errors.value + row
            Log.w(TAG, "+ [${row.id}] ${row.source}: ${row.message}")
            return row.id
        }
    }

    /** Removes an error by id. A no-op when it is not there. */
    fun removeError(id: String) {
        synchronized(lock) {
            val before = _errors.value
            val after = before.filterNot { it.id == id }
            if (after.size == before.size) return
            deleteById(id)
            _errors.value = after
            Log.i(TAG, "- [$id] cleared (${after.size} remaining)")
        }
    }

    /**
     * Removes whichever row this known error raised, without needing its id.
     *
     * The shape almost every caller wants: a condition is re-evaluated and cleared if it has been
     * fixed, by code that never held on to an id.
     */
    fun removeError(error: KnownError) = removeErrorByKey(error.key)

    /** Removes whichever row carries this key. The ad-hoc counterpart of [removeError]. */
    fun removeErrorByKey(key: String) {
        synchronized(lock) {
            val match = _errors.value.firstOrNull { it.key == key } ?: return
            deleteById(match.id)
            _errors.value = _errors.value.filterNot { it.id == match.id }
            Log.i(TAG, "- [${match.id}] $key cleared (${_errors.value.size} remaining)")
        }
    }

    /**
     * Empties the table.
     *
     * For a deliberate reset only. Note that "exit device" does NOT call this: shutting the app down
     * is not the same as declaring its problems solved, and the log is meant to outlive a restart.
     */
    fun clear() {
        synchronized(lock) {
            if (_errors.value.isEmpty()) return
            Log.i(TAG, "clearing ${_errors.value.size} error(s)")
            runCatching { helper?.writableDatabase?.use { it.delete(ErrorLogDbHelper.TABLE, null, null) } }
            _errors.value = emptyList()
        }
    }

    // ---- SQLite -------------------------------------------------------------------------------- //

    private fun readAll(): List<AppError> = try {
        helper?.readableDatabase?.use { db ->
            db.query(
                ErrorLogDbHelper.TABLE,
                arrayOf(
                    ErrorLogDbHelper.COL_ID, ErrorLogDbHelper.COL_KEY,
                    ErrorLogDbHelper.COL_MESSAGE, ErrorLogDbHelper.COL_SOURCE,
                    ErrorLogDbHelper.COL_AT_MS
                ),
                null, null, null, null, "${ErrorLogDbHelper.COL_AT_MS} ASC"
            ).use { c ->
                val out = ArrayList<AppError>(c.count)
                while (c.moveToNext()) {
                    out += AppError(
                        id = c.getString(0),
                        key = c.getString(1),
                        message = c.getString(2),
                        source = if (c.isNull(3)) null else c.getString(3),
                        atMs = c.getLong(4)
                    )
                }
                out
            }
        } ?: emptyList()
    } catch (e: Exception) {
        Log.e(TAG, "could not read the error log", e)
        emptyList()
    }

    private fun insert(row: AppError) {
        try {
            helper?.writableDatabase?.use { db ->
                db.insertWithOnConflict(
                    ErrorLogDbHelper.TABLE, null,
                    ContentValues().apply {
                        put(ErrorLogDbHelper.COL_ID, row.id)
                        put(ErrorLogDbHelper.COL_KEY, row.key)
                        put(ErrorLogDbHelper.COL_MESSAGE, row.message)
                        put(ErrorLogDbHelper.COL_SOURCE, row.source)
                        put(ErrorLogDbHelper.COL_AT_MS, row.atMs)
                    },
                    SQLiteDatabase.CONFLICT_REPLACE
                )
            }
        } catch (e: Exception) {
            // Never fatal: failing to persist an error must not take down the thing reporting it.
            Log.e(TAG, "could not persist ${row.key}", e)
        }
    }

    private fun deleteById(id: String) {
        runCatching {
            helper?.writableDatabase?.use {
                it.delete(ErrorLogDbHelper.TABLE, "${ErrorLogDbHelper.COL_ID} = ?", arrayOf(id))
            }
        }.onFailure { Log.e(TAG, "could not delete $id", it) }
    }
}

/**
 * The error log's table.
 *
 * Its own database, and a non-destructive `onUpgrade`, for the same reason `location_map.db` has one:
 * this holds a record of what went wrong, and a schema bump that wiped it would destroy the evidence
 * at exactly the moment somebody is looking for it.
 *
 * Deliberately NOT dropped by "clean memory". A clean is for reclaiming space from working files; the
 * log is a few hundred bytes and the problems it lists do not stop being true because someone freed
 * some disk.
 */
class ErrorLogDbHelper(context: Context) :
    SQLiteOpenHelper(context.applicationContext, DB_NAME, null, DB_VERSION) {

    override fun onCreate(db: SQLiteDatabase) {
        db.execSQL(
            """
            CREATE TABLE $TABLE (
                $COL_ID      TEXT    PRIMARY KEY,
                $COL_KEY     TEXT    NOT NULL,
                $COL_MESSAGE TEXT    NOT NULL,
                $COL_SOURCE  TEXT,
                $COL_AT_MS   INTEGER NOT NULL
            )
            """.trimIndent()
        )
        // One row per condition: the key is what de-duplicates, so the index is on the lookup path.
        db.execSQL("CREATE UNIQUE INDEX idx_error_key ON $TABLE($COL_KEY)")
    }

    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        // Intentionally empty — see the class note. A real migration goes here when the schema moves.
    }

    companion object {
        private const val DB_NAME = "error_log.db"
        private const val DB_VERSION = 1

        const val TABLE = "error_log"
        const val COL_ID = "id"
        const val COL_KEY = "error_key"
        const val COL_MESSAGE = "message"
        const val COL_SOURCE = "source"
        const val COL_AT_MS = "at_ms"
    }
}
